(1, 'RPJMD', 'RPJMD Kabupaten Nias Barat Tahun 2025–2029', NULL, '2025', 'Rencana Pembangunan Jangka Menengah Daerah yang memuat visi \"Mewujudkan Nias Barat CERAH\" (Cerdas, Sejahtera, Sehat). Data awal — lengkapi nomor Perda & unggah dokumen resmi melalui admin.', NULL, NULL, 1, '2026-08-13 06:09:47', '2026-08-13 06:09:47'),
(2, 'RKPD', 'RKPD Kabupaten Nias Barat Tahun 2026', NULL, '2026', 'Rencana Kerja Pemerintah Daerah sebagai penjabaran tahunan RPJMD 2025–2029. Data awal — lengkapi nomor Perbup & unggah dokumen resmi melalui admin.', NULL, NULL, 1, '2026-08-13 06:09:47', '2026-08-13 06:09:47'),
(3, 'RENSTRA', 'Renstra Bappelitbangda Kabupaten Nias Barat 2025–2029', NULL, '2025', 'Rencana Strategis Perangkat Daerah Bappelitbangda, selaras dengan RPJMD 2025–2029. Data awal — lengkapi nomor & unggah dokumen resmi melalui admin.', NULL, NULL, 1, '2026-08-13 06:09:47', '2026-08-13 06:09:47'),
(4, 'RENJA', 'Renja Bappelitbangda Kabupaten Nias Barat Tahun 2026', NULL, '2026', 'Rencana Kerja tahunan Bappelitbangda sebagai dasar evaluasi triwulanan di SICERAH. Data awal — lengkapi nomor & unggah dokumen resmi melalui admin.', NULL, NULL, 1, '2026-08-13 06:09:47', '2026-08-13 06:09:47'),
(5, 'PERDA', 'Peraturan Daerah tentang RPJMD Kabupaten Nias Barat 2025–2029', NULL, '2025', 'Payung hukum penetapan RPJMD. Data awal — lengkapi nomor Perda & unggah dokumen resmi melalui admin.', NULL, NULL, 1, '2026-08-13 06:09:47', '2026-08-13 06:09:47'),
(6, 'PERBUP', 'Peraturan Bupati tentang RKPD Kabupaten Nias Barat Tahun 2026', NULL, '2026', 'Payung hukum penetapan RKPD tahun berjalan. Data awal — lengkapi nomor Perbup & unggah dokumen resmi melalui admin.', NULL, NULL, 1, '2026-08-13 06:09:47', '2026-08-13 06:09:47');
